from format_lecon import Lesson,paras,table,steps
l=Lesson('Syndrome de Duane',9)
l.add('Le {syndrome de Duane est un trouble congénital de l’innervation oculaire}. Il limite certains mouvements horizontaux et peut rétracter le globe. Il ne correspond pas à une simple paralysie acquise du VI.',paras('Le rapport SFO décrit une innervation anormale du droit latéral, avec hypoplasie ou absence du VI et participation aberrante de fibres du III dans certains profils. La contraction simultanée de muscles antagonistes explique la rétraction du globe.', 'Le syndrome peut limiter l’abduction, l’adduction ou les deux. Le rétrécissement de la fente palpébrale lors de l’adduction est un signe caractéristique. Le Royal Berkshire NHS rappelle qu’il s’agit d’une anomalie présente dès la naissance, même si elle est remarquée plus tard.'),(10,19))
l.add('Le {contexte est généralement ancien et peu évolutif sur le plan neurologique}. L’enfant peut adopter une posture qui permet une vision binoculaire utile. Une découverte tardive ne prouve pas une apparition récente.',paras('Aucune prévalence suisse comparative récente n’a été retrouvée pour classer ce diagnostic parmi les causes de strabisme. Les sources retenues servent à reconnaître le mécanisme et à organiser le suivi, sans inventer un rang de fréquence.', 'L’histoire des premières photographies, les observations parentales et les anciens examens aident à dater l’anomalie. La déviation et la posture peuvent devenir plus visibles selon les exigences visuelles ou la compensation.', 'Un début réellement aigu, une douleur, une baisse visuelle ou un signe neurologique ne s’expliquent pas automatiquement par un syndrome congénital. Ces éléments imposent de rechercher une autre cause ou une atteinte associée.'),(4,10,19))
l.add('La {co-contraction musculaire explique la rétraction et les mouvements atypiques}. Le muscle ne reçoit pas une commande normale dans tous les regards. La chirurgie ne recrée pas l’innervation absente.',table(['Mécanisme','Signe recherché','Conséquence'],[['Le droit latéral est mal innervé.','Abduction limitée, parfois associée à une limitation d’adduction.','Distinguer l’anomalie congénitale d’une neuropathie acquise.'],['Deux muscles horizontaux se contractent ensemble.','Rétraction du globe et fente palpébrale rétrécie en adduction.','Intégrer ce signe au diagnostic et au choix chirurgical.'],['Le déplacement du globe devient atypique en adduction.','Élévation ou abaissement brusque du globe dans certains profils.','Quantifier le phénomène sans l’assimiler automatiquement à une paralysie verticale.'],['Une posture rapproche les yeux d’une zone de fusion.','Tête tournée avec meilleur alignement fonctionnel.','Préserver une adaptation utile et évaluer son retentissement.']])+paras('Le déficit mesuré dans un regard extrême n’est pas le seul objectif thérapeutique. L’alignement en position primaire, la vision, la posture et le confort quotidien guident les décisions. Promettre une abduction normale après chirurgie serait trompeur.'),(10,19))
l.add('La {démarche exclut d’abord une limitation nouvellement acquise}. Une douleur ou un signe neurologique demande une autre explication. Chez l’enfant, ne pas omettre l’examen de la vision et du fond d’œil.',paras('Une paralysie acquise du VI peut produire un déficit d’abduction, mais n’explique pas le profil classique de rétraction congénitale. La chronologie, la fente palpébrale et les mouvements associés aident à les distinguer.', 'Une restriction orbitaire, une autre anomalie congénitale ou une lésion neurologique peuvent imiter certains éléments. Une apparition aiguë chez l’enfant relève du parcours de strabisme paralytique urgent, même sans céphalée.', 'Une leucocorie, un reflet pupillaire anormal ou une baisse de vision ne doivent pas être attribués au syndrome de Duane. Ils conduisent à un bilan ophtalmologique approprié et rapide.'),(4,9,10,19))
l.add('L’{anamnèse recherche ancienneté et adaptation posturale}. Demander dans quelles situations l’enfant tourne la tête. Préciser diplopie, fatigue visuelle et difficultés scolaires.',paras('Les parents peuvent décrire une tête tournée pour regarder la télévision, lire ou fixer de loin. Des photographies anciennes objectivent parfois une posture bien avant le diagnostic. L’absence de plainte de diplopie ne signifie pas que les deux yeux voient également.', 'Rechercher traitements optiques antérieurs, amblyopie, interventions et évolution de la déviation. Évaluer le retentissement cervical, l’inconfort et les difficultés relationnelles liées à l’aspect des yeux.', 'Préciser tout signe atypique ou associé. Une aggravation récente, une douleur ou un symptôme neurologique doivent être signalés séparément de l’histoire congénitale.'),(3,10,19))
l.add('L’{examen observe les mouvements et la fente palpébrale}. Mesurer la vision de chaque œil et l’alignement. Comparer abduction et adduction sans forcer la posture.',paras('Observer d’abord la position spontanée de tête et l’alignement dans cette position. Examiner ensuite la position primaire, puis les regards latéraux. La rétraction du globe et le rétrécissement palpébral en adduction sont recherchés de façon comparative.', 'Mesurer la déviation avec les tests à l’écran et les prismes selon la coopération. Rechercher mouvements verticaux brusques en adduction, vision binoculaire et stéréoscopie au bilan spécialisé.', 'Vérifier réfraction et fond d’œil pour identifier un trouble associé ou une cause d’amblyopie. Le Royal Berkshire NHS recommande de ne pas contraindre systématiquement l’enfant à supprimer une posture qui améliore sa vision.'),(3,10,19))
l.add('Les {profils varient selon les limitations et la déviation primaire}. Certains sont surtout ésotropes, d’autres exotropes ou bien alignés. La classification ne remplace pas les mesures individuelles.',paras('7.1. Un profil peut être dominé par une limitation d’abduction avec adduction relativement préservée. Une ésotropie peut alors être visible en position primaire.', '7.2. Un autre profil peut comporter une limitation d’adduction plus marquée ou une limitation dans les deux directions. La déviation primaire peut différer de celle du profil précédent.', '7.3. Rétraction et mouvements verticaux associés ont une intensité variable. Une atteinte bilatérale ou une anomalie associée nécessite une analyse des deux yeux, pas une transposition automatique du schéma unilatéral.'),(19,))
l.add('Le {diagnostic positif repose sur un profil congénital cohérent}. L’association des limitations et de la rétraction est déterminante. Une présentation atypique doit être réévaluée.',paras('La limitation horizontale ancienne, la rétraction en adduction et le rétrécissement palpébral forment un ensemble caractéristique. L’histoire et l’examen spécialisé permettent de distinguer un syndrome de Duane d’une paralysie récente du VI.', 'L’absence d’un signe spectaculaire sur un examen peu coopérant ne suffit pas à conclure. Répéter l’observation et confronter les informations plutôt que donner une étiquette sur la seule abduction limitée.', 'La connaissance du mécanisme explique pourquoi une opération peut améliorer alignement et posture sans restaurer une commande nerveuse normale. Le diagnostic et les objectifs doivent être expliqués à l’enfant et à ses parents.'),(10,19))
l.add('Les {examens complémentaires ciblent fonction visuelle et atypies}. Le diagnostic est habituellement clinique et orthoptique. L’imagerie n’est pas un remplacement systématique de l’examen.',paras('9.a. Le bilan spécialisé décrit motilité, rétraction et alignement ; aucun examen sanguin ne confirme le syndrome de Duane.', '9.b. Mesurer acuités, réfraction, fixation, déviation et vision binoculaire. Le fond d’œil vérifie l’absence de cause organique associée à une baisse visuelle.', '9.c. Adapter les tests à l’âge et à la coopération. Les observations parentales ou photographies aident à documenter l’ancienneté, sans remplacer la mesure de vision.', '9.d. Une chronologie atypique, une progression ou des signes associés justifient des examens ciblés, éventuellement une imagerie selon le spécialiste. Les examens forcés ou peropératoires appartiennent à la planification chirurgicale, pas au dépistage ordinaire.')+table(['Situation','Décision'],[['Le profil congénital typique est stable et la vision bonne.','Suivi fonctionnel et information.'],['Une amblyopie ou une amétropie est détectée.','Correction optique et traitement visuel adaptés.'],['La posture ou la déviation primaire est gênante.','Évaluation strabologique pour les options thérapeutiques.'],['La limitation apparaît récemment avec d’autres signes.','Rechercher une cause acquise et son urgence.']]),(3,4,10,19))
l.add('L’{algorithme protège la vision avant de corriger l’apparence}. Confirmer le mécanisme et évaluer l’adaptation. Traiter ce qui gêne réellement la fonction ou la posture.',steps('Vérifier ancienneté et absence d’alarme acquise.', 'Documenter rétraction, limitations et déviation dans les regards utiles.', 'Mesurer la vision et traiter une amétropie ou une amblyopie associée.', 'Observer si la fonction est satisfaisante ; discuter chirurgie si déviation ou posture importante.', 'Réévaluer vision, confort et attentes sans promettre une motilité normale.'),(3,10,19))
l.add('La {prise en charge est individualisée et souvent conservatrice}. Un syndrome bien compensé peut ne pas nécessiter de chirurgie. Les lunettes et le suivi visuel répondent aux troubles associés.',paras('11.A. Les objectifs sont une bonne vision de chaque œil, un alignement utile et une posture confortable. La gêne doit être discutée avec la famille en tenant compte de l’âge.', '11.B. Corriger les troubles réfractifs et traiter l’amblyopie selon le bilan, comme exposé dans le cours commun. La limitation d’abduction isolée n’est pas une indication automatique à un médicament ni à une opération.', '11.B. La chirurgie spécialisée peut améliorer déviation primaire, posture, rétraction ou mouvements verticaux gênants. Son choix dépend du profil et de la mécanique musculaire. Elle ne répare pas l’innervation et ne garantit pas des mouvements normaux.', '11.C. Un signe aigu associé suit son propre parcours urgent ; il ne doit pas être attribué par défaut à l’anomalie connue. Une baisse visuelle chez l’enfant exige un bilan de la cause et du développement visuel.', '11.D. Organiser les contrôles selon âge, acuité et déviation. Informer l’école que la posture peut être une adaptation visuelle utile. Ne pas forcer systématiquement la tête en position droite ; discuter une prise en charge si la posture devient inconfortable ou invalidante.'),(3,10,19))
l.add('La {prévention vise surtout l’amblyopie et le handicap postural}. L’anomalie d’innervation n’est pas prévenue par des exercices. Le suivi reconnaît les problèmes visuels associés.',paras('La prévention primaire du défaut congénital n’est pas établie par les sources retenues. La prévention secondaire repose sur le repérage d’un strabisme ou d’une posture inhabituelle et sur une évaluation précoce.', 'La prévention tertiaire traite amblyopie, amétropie et retentissement fonctionnel. Une information claire évite que les parents ou enseignants suppriment une posture compensatrice utile sans avis spécialisé.'),(3,10,19))
l.add('Les {points clés sont rétraction, ancienneté et objectifs réalistes}. Une limitation d’abduction n’est pas toujours une paralysie du VI. La vision et la posture guident le traitement.',paras('Observer la fente palpébrale en adduction. Rechercher une amblyopie malgré l’absence de diplopie. Une opération ne restaure pas une innervation normale. Un symptôme nouveau doit être évalué comme tel, même chez un enfant avec anomalie congénitale connue.'),(3,10,19))
l.quiz([('Le syndrome de Duane est-il habituellement acquis à l’âge adulte ?','Non ; il est congénital, même si découvert tard.'),('Quel mouvement peut rétracter le globe ?','L’adduction.'),('Quel changement palpébral est caractéristique ?','Un rétrécissement de la fente palpébrale en adduction.'),('Une limitation d’abduction prouve-t-elle une paralysie acquise du VI ?','Non.'),('La tête tournée peut-elle aider la vision ?','Oui.'),('Faut-il forcer systématiquement l’enfant à garder la tête droite ?','Non.'),('Une vision sans diplopie exclut-elle une amblyopie ?','Non.'),('Faut-il mesurer l’acuité de chaque œil ?','Oui.'),('Tous les profils ont-ils la même déviation primaire ?','Non.'),('Un test sanguin confirme-t-il le syndrome ?','Non.'),('Une forme bien compensée doit-elle toujours être opérée ?','Non.'),('La chirurgie répare-t-elle l’innervation ?','Non ; elle vise des objectifs mécaniques et fonctionnels.'),('Une leucocorie doit-elle être attribuée au syndrome ?','Non ; elle impose un bilan urgent.'),('Une douleur ou un déficit récent change-t-il la démarche ?','Oui ; rechercher une cause acquise ou associée.')],(3,4,10,19))
l.write()
